code_snippets.typescript_topic_data_structure:

// Frontend Topic data structure - used for both AI-extracted and manually entered topics
interface Topic {
  id?: string; // Optional: client-side generated ID for React keys/management
  title: string;
  description?: string;
}

// Example of how topics might be managed in frontend state
const [currentTopics, setCurrentTopics] = useState<Topic[]>([]);

// Function to add a new manual topic
const addManualTopic = (title: string, description?: string) => {
  const newTopic: Topic = { id: uuidv4(), title, description }; // Assuming uuidv4 for temporary client-side ID
  setCurrentTopics(prevTopics => [...prevTopics, newTopic]);
};

// Function to update a manual topic
const updateManualTopic = (id: string, newTitle: string, newDescription?: string) => {
  setCurrentTopics(prevTopics =>
    prevTopics.map(topic =>
      topic.id === id ? { ...topic, title: newTitle, description: newDescription } : topic
    )
  );
};

// Function to remove a manual topic
const removeManualTopic = (id: string) => {
  setCurrentTopics(prevTopics => prevTopics.filter(topic => topic.id !== id));
};

